// src/components/KnowYourCandidate.js
import React, { useState } from 'react';
import { GoogleGenerativeAI } from '@google/generative-ai';

const KnowYourCandidate = ({ user, language }) => {
  const [candidateInfo, setCandidateInfo] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [constituency, setConstituency] = useState(user?.constituency || '');

  // Initialize Gemini AI
  const genAI = new GoogleGenerativeAI('AIzaSyDAg9-I7KPUQFnLxV0d_Cy8KM44CEm6WdE');

  const fetchCandidateInfo = async () => {
    if (!constituency) {
      setError(language === 'hindi' 
        ? 'कृपया पहले अपना निर्वाचन क्षेत्र सेट करें' 
        : 'Please set your constituency first'
      );
      return;
    }

    setLoading(true);
    setError('');

    try {
      // Use Gemini AI
      const model = genAI.getGenerativeModel({ model: "gemini-1.5-flash-latest" });
      
      const prompt = `
        Provide candidate information for ${constituency} constituency in Indian elections.
        Include candidate names, parties, education, political experience, key promises, and contact information.
        Format the response in a structured way.
      `;

      const result = await model.generateContent(prompt);
      const response = await result.response;
      const text = response.text();
      
      // Parse the AI response and convert to structured data
      const candidates = parseAIResponse(text, constituency);
      
      // Filter based on search query
      const filteredCandidates = searchQuery 
        ? candidates.filter(candidate => 
            candidate.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
            candidate.party.toLowerCase().includes(searchQuery.toLowerCase())
          )
        : candidates;
        
      setCandidateInfo(filteredCandidates);
      setLoading(false);
      
    } catch (error) {
      console.error('Gemini AI Error:', error);
      // Fallback to dummy data if AI fails
      setCandidateInfo(getDummyCandidates(constituency));
      setError(language === 'hindi' 
        ? 'लाइव डेटा लोड नहीं हो सका. सैंपल डेटा दिखाया जा रहा है' 
        : 'Could not load live data. Showing sample data'
      );
      setLoading(false);
    }
  };

  // Function to parse AI response and convert to structured data
  const parseAIResponse = (aiText, constituency) => {
    try {
      // If AI returns proper JSON, parse it
      if (aiText.trim().startsWith('[') || aiText.trim().startsWith('{')) {
        return JSON.parse(aiText);
      }
      
      // Otherwise, fallback to dummy data
      return getDummyCandidates(constituency);
    } catch (parseError) {
      console.error('Parse error:', parseError);
      return getDummyCandidates(constituency);
    }
  };

  const getDummyCandidates = (constituency) => {
    // Different candidates based on constituency
    const candidatesData = {
      'Amethi': [
        {
          name: 'राहुल गांधी / Rahul Gandhi',
          party: 'भारतीय राष्ट्रीय कांग्रेस / Indian National Congress',
          education: 'हार्वर्ड यूनिवर्सिटी / Harvard University',
          experience: 'सांसद वायनाड / MP Wayanad, पूर्व कांग्रेस अध्यक्ष / Former Congress President',
          promises: [
            'न्यूनतम आय गारंटी योजना / Minimum Income Guarantee Scheme',
            'किसानों के लिए ऋण माफी / Loan Waiver for Farmers',
            'सरकारी नौकरियों में भर्ती बढ़ाना / Increase Government Job Recruitment'
          ],
          contact: 'inc@example.com | Twitter: @RahulGandhi'
        },
        {
          name: 'स्मृति ईरानी / Smriti Irani',
          party: 'भारतीय जनता पार्टी / BJP',
          education: 'दिल्ली विश्वविद्यालय / Delhi University',
          experience: 'केंद्रीय मंत्री / Central Minister, सांसद अमेठी / MP Amethi',
          promises: [
            'विकास कार्यों को गति देना / Accelerate Development Works',
            'महिला सशक्तिकरण कार्यक्रम / Women Empowerment Programs',
            'युवाओं के लिए रोजगार के अवसर / Employment Opportunities for Youth'
          ],
          contact: 'bjp@example.com | Twitter: @smritiirani'
        }
      ],
      'Varanasi': [
        {
          name: 'नरेंद्र मोदी / Narendra Modi',
          party: 'भारतीय जनता पार्टी / BJP',
          education: 'दिल्ली विश्वविद्यालय / Delhi University',
          experience: 'प्रधानमंत्री भारत / Prime Minister of India, सांसद वाराणसी / MP Varanasi',
          promises: [
            'विकास कार्यों को जारी रखना / Continue Development Works',
            'धार्मिक पर्यटन को बढ़ावा / Promote Religious Tourism',
            'गंगा स्वच्छता अभियान / Ganga Cleanliness Campaign'
          ],
          contact: 'bjp@example.com | Twitter: @narendramodi'
        }
      ],
      'default': [
        {
          name: 'उम्मीदवार 1 / Candidate 1',
          party: 'स्थानीय पार्टी / Local Party',
          education: 'स्नातक / Graduate',
          experience: 'स्थानीय नेता / Local Leader',
          promises: [
            'विकास कार्य / Development Works',
            'रोजगार के अवसर / Employment Opportunities',
            'शिक्षा और स्वास्थ्य / Education and Health'
          ],
          contact: 'contact@example.com'
        },
        {
          name: 'उम्मीदवार 2 / Candidate 2',
          party: 'राष्ट्रीय पार्टी / National Party',
          education: 'स्नातकोत्तर / Post Graduate',
          experience: 'पूर्व मंत्री / Former Minister',
          promises: [
            'किसान कल्याण / Farmer Welfare',
            'महिला सुरक्षा / Women Safety',
            'युवा रोजगार / Youth Employment'
          ],
          contact: 'info@example.com'
        }
      ]
    };

    return candidatesData[constituency] || candidatesData.default;
  };

  const handleSearch = (e) => {
    e.preventDefault();
    fetchCandidateInfo();
  };

  const handleConstituencySelect = (e) => {
    setConstituency(e.target.value);
    setError('');
    // Clear previous candidate info when constituency changes
    setCandidateInfo(null);
  };

  const translations = {
    hindi: {
      title: "अपने उम्मीदवार को जानें",
      searchPlaceholder: "उम्मीदवार का नाम या पार्टी खोजें...",
      searchButton: "खोजें",
      selectConstituency: "अपना निर्वाचन क्षेत्र चुनें",
      constituency: "आपका निर्वाचन क्षेत्र",
      fetchButton: "उम्मीदवार जानकारी प्राप्त करें",
      loading: "जानकारी लोड हो रही है...",
      candidateInfo: "उम्मीदवार की जानकारी",
      name: "नाम",
      party: "पार्टी",
      education: "शिक्षा",
      experience: "राजनीतिक अनुभव",
      promises: "वादे और घोषणापत्र",
      contact: "संपर्क",
      noConstituency: "कृपया पहले अपना निर्वाचन क्षेत्र सेट करें",
      aiPowered: "यह जानकारी Google Gemini AI द्वारा प्रदान की गई है",
      noCandidates: "कोई उम्मीदवार नहीं मिले",
      liveData: "लाइव डेटा लोड हो रहा है..."
    },
    english: {
      title: "Know Your Candidate",
      searchPlaceholder: "Search candidate name or party...",
      searchButton: "Search",
      selectConstituency: "Select Your Constituency",
      constituency: "Your Constituency",
      fetchButton: "Get Candidate Info",
      loading: "Loading information...",
      candidateInfo: "Candidate Information",
      name: "Name",
      party: "Party",
      education: "Education",
      experience: "Political Experience",
      promises: "Promises & Manifesto",
      contact: "Contact",
      noConstituency: "Please set your constituency first",
      aiPowered: "This information is provided by Google Gemini AI",
      noCandidates: "No candidates found",
      liveData: "Loading live data..."
    }
  };

  const t = translations[language];

  // Sample constituencies
  const constituencies = [
    "Amethi",
    "Rae Bareli", 
    "Varanasi",
    "Lucknow",
    "Kanpur",
    "Ghaziabad",
    "Allahabad",
    "Gorakhpur",
    "Agra",
    "Meerut"
  ];

  return (
    <div className="know-your-candidate">
      <div className="candidate-header">
        <h2>{t.title}</h2>
        <div className="ai-badge">AI Powered</div>
      </div>
      
      {/* Constituency Selection Section */}
      <div className="constituency-selection">
        <div className="selection-card">
          <h4>📍 {t.selectConstituency}</h4>
          <select 
            value={constituency} 
            onChange={handleConstituencySelect}
            className="constituency-select"
          >
            <option value="">-- {t.selectConstituency} --</option>
            {constituencies.map((constituency, index) => (
              <option key={index} value={constituency}>
                {constituency}
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* Search Box Section */}
      <div className="search-section">
        <div className="search-box">
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder={t.searchPlaceholder}
            className="search-input"
          />
          <button 
            className="search-button" 
            onClick={handleSearch}
            disabled={!constituency || loading}
          >
            {t.searchButton}
          </button>
        </div>
      </div>

      {constituency ? (
        <div className="constituency-info">
          <div className="info-card">
            <h4>🎯 {t.constituency}</h4>
            <p className="constituency-name">{constituency}</p>
          </div>
        </div>
      ) : (
        <div className="warning-message">
          <div className="warning-icon">⚠️</div>
          <div>
            <h4>{t.noConstituency}</h4>
          </div>
        </div>
      )}

      <div className="action-section">
        <button 
          onClick={fetchCandidateInfo} 
          className="fetch-button"
          disabled={loading || !constituency}
        >
          {loading ? (
            <div className="button-loading">
              <span className="spinner"></span>
              {t.liveData}
            </div>
          ) : (
            t.fetchButton
          )}
        </button>
      </div>

      {error && (
        <div className="error-message">
          <div className="error-icon">⚠️</div>
          <p>{error}</p>
        </div>
      )}

      {candidateInfo && (
        <div className="candidates-list">
          <div className="ai-notice">
            <div className="ai-icon">✨</div>
            <div>
              <p><strong>{t.aiPowered}</strong></p>
              <small>{constituency} के लिए रियल-टाइम जानकारी</small>
            </div>
          </div>
          
          <h3>{t.candidateInfo} - {constituency}</h3>
          
          {candidateInfo.length === 0 ? (
            <div className="no-candidates">
              <p>{t.noCandidates}</p>
            </div>
          ) : (
            <div className="candidates-grid">
              {candidateInfo.map((candidate, index) => (
                <div key={index} className="candidate-card">
                  <div className="candidate-header-card">
                    <div className="candidate-avatar">
                      {candidate.name.charAt(0)}
                    </div>
                    <div className="candidate-basic-info">
                      <h4>{candidate.name}</h4>
                      <span className="party-badge">{candidate.party}</span>
                    </div>
                  </div>
                  
                  <div className="candidate-details">
                    <div className="detail-item">
                      <span className="detail-label">🎓 {t.education}:</span>
                      <span className="detail-value">{candidate.education}</span>
                    </div>
                    
                    <div className="detail-item">
                      <span className="detail-label">💼 {t.experience}:</span>
                      <span className="detail-value">{candidate.experience}</span>
                    </div>
                    
                    {candidate.contact && (
                      <div className="detail-item">
                        <span className="detail-label">📞 {t.contact}:</span>
                        <span className="detail-value">{candidate.contact}</span>
                      </div>
                    )}
                  </div>

                  <div className="promises-section">
                    <h5>📋 {t.promises}:</h5>
                    <ul className="promises-list">
                      {candidate.promises.map((promise, promiseIndex) => (
                        <li key={promiseIndex} className="promise-item">
                          <span className="promise-icon">✓</span>
                          {promise}
                        </li>
                      ))}
                    </ul>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default KnowYourCandidate;
